#!/usr/bin/expect -f
# Usage: dutssh.exp <timeout> "<cmd1>" "<cmd2>" ...
# ssh admin@DUT -> su root -> run commands -> exit
set tmo [lindex $argv 0]
set cmds [lrange $argv 1 end]
set timeout $tmo
log_user 1
spawn ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PreferredAuthentications=password -o PubkeyAuthentication=no admin@192.168.127.253
expect { -re "assword:" { send "moxa\r" } timeout { exit 3 } }
expect { -re {\$ $} { } timeout { exit 3 } }
send "su\r"
expect { -re "assword:" { send "moxa\r" } timeout { exit 4 } }
expect { -re {# $} { } timeout { exit 4 } }
send "PS1='RDY># '\r"
expect -re {RDY># $}
foreach c $cmds {
    send "$c\r"
    expect { -re {RDY># $} { } timeout { puts "\n***TIMEOUT on: $c"; } }
}
send "exit\r"
send "exit\r"
expect eof

